def even_odd_palindrome(n):
    evens, odds = 0, 0
    for i in range(1, n+1):
        if i == int(str(i)[::-1]) and i % 2 == 0:
            evens += 1
        elif i == int(str(i)[::-1]):
            odds += 1
    return (evens, odds)

# Test cases
